 39→@Component({
 40→  selector: "tfc-player-view",
 41→  changeDetection: ChangeDetectionStrategy.OnPush,
 42→  providers: [ExerciseStore, TickService],
 43→  imports: [
 44→    ClockDisplayComponent,
 45→    PhaseBadgeComponent,
 46→    AmbientBackgroundComponent,
 47→    BriefingOverlayComponent,
 48→    CompletionOverlayComponent,
 49→    LogsDrawerComponent,
