130→export class HomeView implements OnInit {
131→  private readonly http = inject(HttpClient);
132→  private readonly router = inject(Router);
133→  private readonly exerciseApi = inject(ExerciseApiService);
134→  private readonly engineApi = inject(EngineApiService);
135→  private readonly waitingRoomApi = inject(WaitingRoomApiService);
136→
137→  protected readonly lobbyData = signal<JoinableExercise[]>([]);
138→  protected readonly showPicker = signal(false);
139→  protected readonly pendingScenario = signal<ScenarioResponse | null>(null);
140→
141→  ngOnInit(): void {
142→    this.checkForJoinableExercises();
143→  }
144→
145→  protected onScenarioPicked(scenario: ScenarioResponse): void {
146→    const gameMode = scenario.content?.game_mode ?? "classic";
147→    if (gameMode === "simple_collaborative") {
148→      this.showPicker.set(false);
149→      this.pendingScenario.set(scenario);
150→      return;
151→    }
152→    this.createAndShowLobby(scenario, false);
153→  }
154→
155→  protected createMultiplayer(playerCountMode: "full" | "two_player"): void {
156→    const scenario = this.pendingScenario();
157→    if (!scenario) return;
158→    this.pendingScenario.set(null);
159→    this.createAndShowLobby(scenario, false, playerCountMode);
160→  }
161→
162→  protected createPractice(): void {
163→    const scenario = this.pendingScenario();
164→    if (!scenario) return;
165→    this.pendingScenario.set(null);
166→    const gameMode = scenario.content?.game_mode ?? "simple_collaborative";
167→
168→    this.exerciseApi
169→      .create({
170→        title: scenario.title,
171→        scenario_id: scenario.id,
172→        game_mode: gameMode,
173→        practice_mode: true,
174→      })
175→      .pipe(
176→        switchMap((exercise) =>
177→          this.waitingRoomApi.join(exercise.id, "Player", "all_roles").pipe(
178→            switchMap((participant) =>
179→              this.engineApi.start(exercise.id).pipe(
180→                switchMap(() => {
181→                  this.router.navigate(["/player"], {
182→                    queryParams: {
183→                      exerciseId: exercise.id,
184→                      participantId: participant.id,
185→                      role: "all_roles",
186→                      gameMode: "simple_collaborative",
187→                      practiceMode: true,
188→                    },
189→                  });
190→                  return [];
191→                }),
192→              ),
193→            ),
194→          ),
195→        ),
196→      )
197→      .subscribe();
198→  }
199→
200→  private createAndShowLobby(
201→    scenario: ScenarioResponse,
202→    practiceMode: boolean,
203→    playerCountMode?: "full" | "two_player",
204→  ): void {
205→    const gameMode = scenario.content?.game_mode ?? "classic";
206→    this.exerciseApi
207→      .create({
208→        title: scenario.title,
209→        scenario_id: scenario.id,
210→        game_mode: gameMode,
211→        practice_mode: practiceMode,
212→      })
213→      .subscribe({
214→        next: (exercise) => {
215→          this.router.navigate(["/waiting-room"], {
216→            queryParams: {
217→              exerciseId: exercise.id,
218→              ...(playerCountMode ? { playerCountMode } : {}),
219→            },
220→          });
221→        },
222→      });
223→  }
224→
225→  protected joinExercise(): void {
226→    this.router.navigate(["/waiting-room"], {
227→      queryParams: { browse: true },
228→    });
229→  }
230→
231→  private checkForJoinableExercises(): void {
232→    this.http
233→      .get<
234→        JoinableExercise[]
235→      >(`${environment.apiBaseUrl}/api/exercises/joinable`)
236→      .subscribe({
237→        next: (data) => this.lobbyData.set(data),
238→        error: () => this.lobbyData.set([]),
239→      });
240→  }
241→}
