 89→export const ExerciseStore = signalStore(
 90→  withState(initialState),
 91→
 92→  withComputed((store) => ({
 93→    rtClock: computed(() => formatTimeMs(store.realTimeMs())),
 94→    ptClock: computed(() => formatTimeMs(store.playTimeMs())),
 95→    activeEvents: computed(() =>
 96→      store.events().filter((e) => e.lifecycle === "running"),
 97→    ), // active injects
 98→    scheduledEvents: computed(() =>
 99→      store.events().filter((e) => e.lifecycle === "scheduled"),
100→    ), // scheduled injects
101→    completedEvents: computed(() =>
102→      store.events().filter((e) => e.lifecycle === "completed"),
103→    ), // completed injects
104→    activeIssues: computed(() =>
105→      store.issues().filter((i) => i.lifecycle === "active"),
106→    ), // active defects
107→    /** Remaining ms on the active decision timer (null if no open decision with timeout). */
108→    decisionCountdownMs: computed(() => {
109→      const decision = store
110→        .decisions()
111→        .find((d) => d.status === "open" && d.timeout_ms > 0);
112→      if (!decision) return null;
113→      const deadline = decision.opened_at_pt_ms + decision.timeout_ms;
114→      return Math.max(0, deadline - store.playTimeMs());
115→    }),
116→    /** Countdown clock: decision timer when a decision is open, otherwise time to next event. */
117→    turnCountdownClock: computed(() => {
118→      // Prefer decision countdown when an open decision has a timeout
119→      const decision = store
120→        .decisions()
121→        .find((d) => d.status === "open" && d.timeout_ms > 0);
122→      if (decision) {
123→        const deadline = decision.opened_at_pt_ms + decision.timeout_ms;
124→        return formatTimeMs(Math.max(0, deadline - store.playTimeMs()));
125→      }
126→      const pt = store.playTimeMs();
127→      const nextEvent = store
128→        .events()
129→        .filter((e) => e.lifecycle === "scheduled" && e.scheduled_pt_ms > pt)
130→        .sort((a, b) => a.scheduled_pt_ms - b.scheduled_pt_ms)[0];
131→      if (!nextEvent) return null;
132→      const remaining = Math.max(0, nextEvent.scheduled_pt_ms - pt);
133→      return formatTimeMs(remaining);
134→    }),
135→    issuesWithCountdown: computed(() => {
136→      const pt = store.playTimeMs();
137→      return store
138→        .issues()
139→        .filter(
140→          (i) =>
141→            i.lifecycle === "active" &&
142→            i.auto_resolve_ms > 0 &&
143→            i.activated_at_pt_ms !== null,
144→        )
145→        .map((i) => {
146→          const elapsed = pt - (i.activated_at_pt_ms ?? 0);
147→          const remaining = Math.max(0, i.auto_resolve_ms - elapsed);
148→          return { ...i, remaining_ms: remaining };
149→        });
150→    }),
151→    releasedIssues: computed(() => store.issues().filter((i) => i.released)),
152→    openDecisions: computed(() =>
153→      store.decisions().filter((d) => d.status === "open"),
154→    ),
155→    hasOpenDecision: computed(
156→      () => store.decisions().filter((d) => d.status === "open").length > 0,
157→    ),
158→    connectedParticipants: computed(() =>
159→      store.participants().filter((p) => p.connected),
160→    ),
161→    connectedCount: computed(
162→      () => store.participants().filter((p) => p.connected).length,
163→    ),
164→    isCollaborative: computed(
165→      () => store.gameMode() === "simple_collaborative",
166→    ),
167→    isDecisionMaker: computed(() => store.playerType() === "decision_maker"),
168→    isAllAdvisors: computed(() => store.playerRole() === "all_advisors"),
169→    isPracticeMode: computed(() => store.practiceMode()),
170→    phaseBadgeVariant: computed<"default" | "secondary" | "destructive">(() => {
171→      switch (store.phase()) {
172→        case "running":
173→          return "default";
174→        case "paused":
175→          return "secondary";
176→        case "completed":
177→          return "destructive";
178→        default:
179→          return "secondary";
180→      }
181→    }),
182→  })),
183→
184→  withMethods((store) => ({
185→    setExerciseId(id: number): void {
186→      patchState(store, { exerciseId: id });
187→    },
188→
189→    applySnapshot(snapshot: SnapshotWithScore): void {
190→      patchState(store, {
191→        exerciseId: snapshot.exercise_id,
192→        title: snapshot.title,
193→        phase: snapshot.phase,
194→        playTimeMs: snapshot.time.play_time_ms,
195→        realTimeMs: snapshot.time.real_time_ms,
196→        speedFactor: snapshot.time.factor,
197→        paused: snapshot.time.paused,
198→        events: snapshot.events,
199→        issues: snapshot.issues,
200→        systems: snapshot.systems ?? store.systems(),
201→        warfareDomains: snapshot.warfare_domains ?? store.warfareDomains(),
202→        decisions: snapshot.decisions ?? store.decisions(),
203→        score: snapshot.score
204→          ? {
205→              stress: snapshot.score.stress,
206→              turnNumber: snapshot.score.turn_number,
207→              nextDecisionTimeMs: snapshot.score.next_decision_time_ms,
208→              scoreTier: snapshot.score.score_tier ?? null,
209→            }
210→          : store.score(),
211→        loading: false,
212→        error: null,
213→      });
214→    },
215→
216→    applyTimeUpdate(time: TimeSnapshot): void {
217→      patchState(store, {
218→        playTimeMs: time.play_time_ms,
219→        realTimeMs: time.real_time_ms,
220→        speedFactor: time.factor,
221→        paused: time.paused,
222→      });
223→    },
224→
225→    /** Advance clocks locally by wall-clock delta (call from a setInterval). */
226→    tick(wallDeltaMs: number): void {
227→      if (store.paused()) return;
228→      const factor = store.speedFactor();
229→      patchState(store, {
230→        realTimeMs: store.realTimeMs() + wallDeltaMs,
231→        playTimeMs: store.playTimeMs() + wallDeltaMs * factor,
232→      });
233→    },
234→
235→    applyPhaseChange(phase: string): void {
236→      patchState(store, { phase });
237→    },
238→
239→    updateEvent(eventId: string, lifecycle: string): void {
240→      const events = store
241→        .events()
242→        .map((e) => (e.id === eventId ? { ...e, lifecycle } : e));
243→      patchState(store, { events });
244→    },
245→
246→    updateIssue(issueId: string, lifecycle: string, released?: boolean): void {
247→      const issues = store
248→        .issues()
249→        .map((i) =>
250→          i.id === issueId
251→            ? { ...i, lifecycle, released: released ?? i.released }
252→            : i,
253→        );
254→      patchState(store, { issues });
255→    },
256→
257→    setLoading(loading: boolean): void {
258→      patchState(store, { loading });
259→    },
260→
261→    setError(error: string): void {
262→      patchState(store, { error, loading: false });
263→    },
264→
265→    applyDecisions(decisions: ActiveDecision[]): void {
266→      patchState(store, { decisions });
267→    },
268→
269→    setContext(ctx: ScenarioContext): void {
270→      patchState(store, { context: ctx });
271→    },
272→
273→    setParticipantId(id: string): void {
274→      patchState(store, { participantId: id });
275→    },
276→
277→    setPlayerRole(role: string): void {
278→      patchState(store, { playerRole: role });
279→    },
280→
281→    closeDecision(decisionId: string, selectedOptionIds?: string[]): void {
282→      const decisions = store.decisions().map((d) =>
283→        d.id === decisionId
284→          ? {
285→              ...d,
286→              status: "closed",
287→              selected_option_ids: selectedOptionIds ?? d.selected_option_ids,
288→            }
289→          : d,
290→      );
291→      patchState(store, { decisions });
292→    },
293→
294→    updatePresence(participants: ParticipantPresence[]): void {
295→      patchState(store, { participants });
296→    },
297→
298→    setGameMode(mode: string): void {
299→      patchState(store, { gameMode: mode });
300→    },
301→
302→    setPracticeMode(practice: boolean): void {
303→      patchState(store, { practiceMode: practice });
304→    },
305→
306→    setPlayerType(playerType: string): void {
307→      patchState(store, { playerType });
308→    },
309→
310→    setSpeedFactor(factor: number): void {
311→      patchState(store, { speedFactor: factor });
312→    },
313→
314→    applyScoreChange(
315→      change: Pick<
316→        ScoreChange,
317→        | "total_score"
318→        | "stress"
319→        | "next_decision_time_ms"
320→        | "turn_number"
321→        | "score_tier"
322→      >,
323→    ): void {
324→      patchState(store, {
325→        score: {
326→          stress: change.stress,
327→          nextDecisionTimeMs: change.next_decision_time_ms,
328→          turnNumber: change.turn_number,
329→          scoreTier: change.score_tier ?? store.score()?.scoreTier ?? null,
330→        },
331→      });
332→    },
333→
334→    applyRecommendation(
335→      decisionId: string,
336→      participantId: string,
337→      optionId: string,
338→    ): void {
339→      const decisions = store.decisions().map((d) =>
340→        d.id === decisionId
341→          ? {
342→              ...d,
343→              recommendations: {
344→                ...d.recommendations,
345→                [participantId]: optionId,
346→              },
347→            }
348→          : d,
349→      );
350→      patchState(store, { decisions });
351→    },
352→
353→    applySystemChange(
354→      change: Pick<
355→        SystemStateChange,
356→        "system_id" | "action" | "power" | "operational"
357→      >,
358→    ): void {
359→      const systems = store
360→        .systems()
361→        .map((s) =>
362→          s.system_id === change.system_id
363→            ? { ...s, power: change.power, operational: change.operational }
364→            : s,
365→        );
366→      patchState(store, { systems });
367→    },
368→
369→    applyWarfareDomainChange(
370→      change: Pick<WarfareDomainChange, "domain_id" | "threat_level">,
371→    ): void {
372→      const warfareDomains = store
373→        .warfareDomains()
374→        .map((d) =>
375→          d.domain_id === change.domain_id
376→            ? { ...d, threat_level: change.threat_level }
377→            : d,
378→        );
379→      patchState(store, { warfareDomains });
380→    },
381→  })),
382→);
