 3→// ── Signal types ────────────────────────────────────────────
 4→
 5→export const enum SignalType {
 6→  Friendly,
 7→  Hostile,
 8→  Neutral,
 9→}
10→
11→export const SIGNAL_COLORS: Record<SignalType, number> = {
12→  [SignalType.Friendly]: 0x22d68a, // green
13→  [SignalType.Hostile]: 0xe84057, // red
14→  [SignalType.Neutral]: 0xd4c35c, // amber
15→};
16→
17→export const MAX_SIGNALS = 18;
18→export const SIGNAL_LIFESPAN = 4; // seconds
19→export const SPAWN_INTERVAL = 0.6; // seconds between spawns
20→
21→export interface Signal {
22→  type: SignalType;
23→  x: number;
24→  z: number;
25→  birth: number;
26→  light: THREE.PointLight;
27→  sprite: THREE.Sprite;
28→}
29→
30→// ── Glow sprite texture (procedural) ───────────────────────
31→
32→export function createGlowTexture(): THREE.Texture {
33→  const size = 64;
34→  const canvas = document.createElement("canvas");
35→  canvas.width = size;
36→  canvas.height = size;
37→  const ctx = canvas.getContext("2d")!;
38→  const gradient = ctx.createRadialGradient(
39→    size / 2,
40→    size / 2,
41→    0,
42→    size / 2,
43→    size / 2,
44→    size / 2,
45→  );
46→  gradient.addColorStop(0, "rgba(255,255,255,1)");
47→  gradient.addColorStop(0.3, "rgba(255,255,255,0.6)");
48→  gradient.addColorStop(1, "rgba(255,255,255,0)");
49→  ctx.fillStyle = gradient;
50→  ctx.fillRect(0, 0, size, size);
51→  const tex = new THREE.CanvasTexture(canvas);
52→  tex.needsUpdate = true;
53→  return tex;
54→}
55→
56→// ── Wave function (shared between mesh + signals) ──────────
57→
58→export function waveY(x: number, z: number, t: number): number {
59→  return (
60→    Math.sin(x * 0.4 + t * 0.6) * 0.35 +
61→    Math.sin(z * 0.55 + t * 0.45) * 0.25 +
62→    Math.sin((x + z) * 0.3 + t * 0.35) * 0.15 +
63→    Math.sin(x * 0.9 - t * 0.25) * 0.1
64→  );
65→}
